#!/usr/bin/env node

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { artifactJsonText, buildForwardPackage, validateForwardPackage } from "../src/forward-package.mjs";
import { parseArgs, writeJsonFile } from "../src/io.mjs";
import { applyLocationMap, locationMappingStats, validateLocationMap } from "../src/location-map.mjs";
import { normalizeKentikPayload } from "../src/normalize.mjs";
import { writeChecksumManifest } from "./release-checksums.mjs";

const usage = `
Build a read-only acceptance evidence bundle

Usage:
  node scripts/acceptance-bundle.mjs --input fixtures/kentik-topxdata.demo.json --output-dir out/acceptance

Options:
  --input path           Kentik Query API response JSON. Default: fixtures/kentik-topxdata.demo.json
  --location-map path    Optional reviewed location map.
  --output-dir path      Output directory. Default: dist/acceptance
`;

const readJson = async (filePath) => JSON.parse(await readFile(filePath, "utf8"));

const acceptanceMarkdown = ({ checksSha256, input, locationMap, outputDir, summary }) => `# Acceptance Evidence

Generated by Forward Integration for Kentik.

## Inputs

- Kentik input: \`${input}\`
- Location map: \`${locationMap || "none"}\`
- Output directory: \`${outputDir}\`

## Results

- Observed flows: ${summary.observedFlows}
- Generated checks: ${summary.generatedChecks}
- Skipped rows: ${summary.skipped}
- Location mappings: from=${summary.locationMapping.fromMapped}, to=${summary.locationMapping.toMapped}, both=${summary.locationMapping.bothMapped}
- Checks SHA-256: \`${checksSha256}\`

## Required Next Steps

1. Review \`observed-flows.json\`, \`forward-kentik-report.json\`, and any skipped rows.
2. Run \`npm run schemas:validate -- --checks ${path.join(outputDir, "forward-intent-checks.json")} --manifest ${path.join(outputDir, "forward-kentik-manifest.json")}\`.
3. Run Forward dry-run against the intended non-production network.
4. Apply only after reviewer approval.

This bundle does not contact Forward and does not create intent checks.
`;

export const buildAcceptanceBundle = async ({ input, locationMapPath, outputDir }) => {
  await mkdir(outputDir, { recursive: true });
  const payload = await readJson(input);
  let flows = normalizeKentikPayload(payload);
  if (locationMapPath) {
    const locationMap = await readJson(locationMapPath);
    validateLocationMap(locationMap);
    flows = applyLocationMap(flows, locationMap);
  }

  const forwardPackage = buildForwardPackage(flows);
  const failures = validateForwardPackage(forwardPackage);
  if (failures.length > 0) {
    throw new Error(`Generated package failed validation:\n${failures.join("\n")}`);
  }

  const paths = {
    checks: path.join(outputDir, "forward-intent-checks.json"),
    manifest: path.join(outputDir, "forward-kentik-manifest.json"),
    observedFlows: path.join(outputDir, "observed-flows.json"),
    report: path.join(outputDir, "forward-kentik-report.json"),
    summary: path.join(outputDir, "acceptance-summary.json"),
    markdown: path.join(outputDir, "ACCEPTANCE.md"),
    checksums: path.join(outputDir, "SHA256SUMS"),
  };

  await writeJsonFile(paths.observedFlows, flows);
  await writeJsonFile(paths.checks, forwardPackage.checks);
  await writeJsonFile(paths.manifest, forwardPackage.manifest);
  await writeJsonFile(paths.report, forwardPackage.report);

  const summary = {
    schemaVersion: "forward-kentik-acceptance/v0.1",
    generatedAt: new Date().toISOString(),
    input,
    locationMap: locationMapPath || null,
    observedFlows: flows.length,
    generatedChecks: forwardPackage.checks.length,
    skipped: forwardPackage.report.skipped.length,
    locationMapping: locationMappingStats(flows),
    checksSha256: forwardPackage.manifest.integrity.intentChecksSha256,
  };
  await writeJsonFile(paths.summary, summary);
  await writeFile(
    paths.markdown,
    acceptanceMarkdown({
      checksSha256: summary.checksSha256,
      input,
      locationMap: locationMapPath,
      outputDir,
      summary,
    }),
    "utf8",
  );
  await writeChecksumManifest({
    files: [paths.checks, paths.manifest, paths.observedFlows, paths.report, paths.summary, paths.markdown],
    outPath: paths.checksums,
  });

  return { ...summary, outputDir, files: Object.values(paths) };
};

const main = async () => {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    process.stdout.write(usage);
    return;
  }

  const result = await buildAcceptanceBundle({
    input: args.input || "fixtures/kentik-topxdata.demo.json",
    locationMapPath: args["location-map"],
    outputDir: args["output-dir"] || "dist/acceptance",
  });
  process.stdout.write(`${artifactJsonText(result)}`);
};

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    process.stderr.write(`${error.stack || error.message}\n`);
    process.exitCode = 1;
  });
}
